-- Daily challenges for 2026-10-13: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-13. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('making-something-with-your-hands', 'Making Something with Your Hands', 'For anyone whose days happen mostly on screens. Each day is one small hands-on making task, from folding, sketching and mending to baking or potting a plant, done for the pleasure of making rather than for a perfect result.', 'Creativity', 365, array['Self-Care', 'Mindfulness']::text[], 1, '2026-10-13T17:00:00+00:00'::timestamptz),
  ('studying-without-the-stress', 'Studying Without the Stress', 'For students and lifelong learners who dread the books. Each day is one small study habit, from a short focused session to a tidy desk or a practice question, that makes learning steadier and the night before a test calmer.', 'Study', 365, array['Stress', 'Habits', 'Goals']::text[], 1, '2026-10-13T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('making-something-with-your-hands', 'studying-without-the-stress');

