  ('studying-without-the-stress', 215, 'Notice the urge to check your phone in the middle of a session and wait until the timer ends.'),
  ('studying-without-the-stress', 216, 'Pick a single study goal for your weekend and let the rest of the weekend be yours.'),
  ('studying-without-the-stress', 217, 'Find a quiet table in a different part of the library than usual and try one session there.'),
  ('studying-without-the-stress', 218, 'Before closing your books, say aloud the three biggest ideas from today''s study.'),
  ('studying-without-the-stress', 219, 'Review flashcards for ten minutes while waiting for a class or appointment to start.'),
  ('studying-without-the-stress', 220, 'If you''re studying for a license or certification, find the official exam outline and print it.'),
  ('studying-without-the-stress', 221, 'Check off each section of your certification exam outline you''ve already covered, and see what''s left.'),
  ('studying-without-the-stress', 222, 'Take one full practice question set for your license exam, then review every answer you missed.'),
  ('studying-without-the-stress', 223, 'Set aside twenty minutes after work to study, before you sit down for the evening.'),
  ('studying-without-the-stress', 224, 'Study for fifteen minutes on your lunch break, then put it away and enjoy the rest of the hour.'),
